INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_sr_b001_003', 'topic_nsmq_phys_waves', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'What is the bending of light as it passes from air into water called?', 'direct_answer', 'speed_race', NULL, 'Refraction', 'Refraction is the change in direction of a wave when its speed changes at a boundary between media. Snell’s law, n₁sinθ₁ = n₂sinθ₂, quantifies it.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_sr_b001_004', 'topic_nsmq_phys_modern_physics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'Which particle is emitted from a nucleus during beta-minus decay?', 'direct_answer', 'speed_race', NULL, 'Electron', 'In beta-minus decay a neutron converts to a proton and emits an electron (the beta particle) plus an antineutrino. The atomic number rises by one while the mass number is unchanged.', 'medium', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_phys_sr_b001_001', 'q_nsmq_phys_sr_b001_002', 'q_nsmq_phys_sr_b001_003', 'q_nsmq_phys_sr_b001_004');
